CREATE TRIGGER edge_limit_edge_observe AFTER INSERT OR DELETE OR UPDATE ON truss.edge FOR EACH ROW EXECUTE FUNCTION truss.edge_limit_observe(); CREATE TRIGGER edge_limit_marker_observe AFTER INSERT OR DELETE OR UPDATE ON truss.edge_limit FOR EACH ROW EXECUTE FUNCTION truss.edge_limit_observe(); CREATE TRIGGER edge_limit_catalog_observe AFTER INSERT OR DELETE OR UPDATE ON truss.rel_def FOR EACH ROW EXECUTE FUNCTION truss.edge_limit_catalog_observe()